  cookie: {
    name: "__ats_session",
    path: "/",
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    secrets: [sessionSecret],
    maxAge: 60 * 60 * 8,
  },
});

export interface SessionUser {
  id: string;
  email: string;
  fullName: string;
  role: UserRole;
}

export async function getSession(request: Request) {
  return sessionStorage.getSession(request.headers.get("Cookie"));
}

