  const row = await db
    .selectFrom("users")
    .select(["id", "email", "full_name", "role"])
    .where("id", "=", userId)
    .where("is_active", "=", true)
    .executeTakeFirst();

  if (!row) {
    return null;
  }

  return { id: row.id, email: row.email, fullName: row.full_name, role: row.role };
